NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'I Peter'

CHAPTERS = {
    1: {
        1: 'Petrus, ein Apostel Jesu Christi, an die auserwählten Fremdlinge in der Zerstreuung in Pontus, Galatien, Kappadocien, Asien und Bithyninen,',
        2: 'Nach dem Ratschlusse Gottes des Vaters durch die Heiligung des Geistes zum Gehorsam und zur Besprengung mit dem Blute Jesu Christi. Gnade und Friede werde euch in Fülle zuteil!',
        3: 'Gelobt sei Gott und der Vater unseres Herrn Jesus Christus, Der uns nach Seiner großen Barmherzigkeit durch die Auferstehung Jesu Christi von den Toten wiedergeboren hat zu einer lebendigen Hoffnung.',
        4: 'Auf ein unvergängliches, unbeflecktes und unverwelkliches Erbteil, das im Himmel aufbehalten ist.',
        5: 'Für euch, die ihr durch die Kraft Gottes mittelst des Glaubens bewahrt werdet für die Seligkeit, die bereit steht, daß sie in der letzten Zeit geoffenbart werde.',
        6: 'Worüber ihr frohlockt, wenn ihr auch jetzt eine kleine Zeit',
        7: 'Auf daß euer Glaube bewährt und viel köstlicher erfunden werde, als das vergängliche, durch Feuer bewährte Gold, zu Lob, Preis und Herrlichkeit bei der Offenbarung Jesu Christi.',
        8: 'Den ihr liebet, ohne Ihn gesehen zu haben, an Den ihr, ohne Ihn jetzt zu sehen, glaubt, und frohlocket mit unaussprechlicher und herrlicher Freude,',
        9: 'Indem ihr als Ziel eures Glaubens der Seelen Seligkeit davontraget;',
        10: 'Nach welcher Seligkeit die Propheten, die von der euch bestimmten Gnade weissagten, eifrig gesucht und geforscht haben,',
        11: 'Indem sie nachforschten, auf welche oder welcherlei Zeit Christi Geist deutete, der in ihnen war, und die Christus bevorstehenden Leiden und die darauf folgenden Herrlichkeiten voraus bezeugte;',
        12: 'Denen geoffenbart worden, daß nicht ihnen selbst, sondern euch zugut kommen sollte, was euch nun durch die, so euch durch den vom Himmel gesandten Heiligen Geist das Evangelium predigten, verkündigt worden ist, in das hineinzuschauen Engel selbst verlangt.',
        13: 'Darum umgürtet die Lenden eures Gemütes, seid nüchtern, und setzt eure volle Hoffnung auf die Gnade, die euch durch die Erscheinung von Jesus Christus dargebracht wird;',
        14: 'Als Kinder des Gehorsams, indem ihr euch nicht mehr richtet nach den Lüsten in eurer früheren Unwissenheit,',
        15: 'Sondern nach dem Heiligen, Der euch berufen hat, auf daß auch ihr in all eurem Wandel heilig werdet.',
        16: 'Weil geschrieben steht: Ihr sollt heilig sein, denn Ich bin heilig.',
        17: 'Und wenn ihr Den als Vater anruft, Der ohne Ansehen der Person richtet, nach eines jeglichen Werk, so wandelt in Furcht die Zeit eurer Pilgerschaft,',
        18: 'Indem ihr ja wißt, daß ihr nicht mit vergänglichem Silber oder Gold von eurem eitlen, von den Vätern angeborenen Wandel erlöst seid,',
        19: 'Sondern mit dem teuren Blut Christi als eines fehllosen und unbefleckten Lammes,',
        20: 'Der vor Gründung der Welt dazu vorausbestimmt war, und in diesen letzten Zeiten um euretwillen Sich geoffenbart hat,',
        21: 'Die ihr durch Ihn glaubt an Gott, Der Ihn von den Toten auferweckt und Ihm Herrlichkeit verliehen hat, so daß ihr Glauben und Hoffnung auf Gott haben möchtet.',
        22: 'Und heiligt eure Seelen im Gehorsam gegen die Wahrheit durch den Geist zu ungeheuchelter Bruderliebe und habt aus reinem Herzen einander inbrünstig lieb,',
        23: 'Als die da wiedergeboren sind nicht aus vergänglichem, sondern aus unvergänglichem Samen, durch das lebendige Wort Gottes, das da ewiglich bleibt.',
        24: 'Denn alles Fleisch ist wie Gras, und all seine Herrlichkeit wie die Blume des Grases: Das Gras verdorrt und seine Blume fällt ab.',
        25: 'Aber des Herrn Wort bleibt in Ewigkeit. Das ist aber das Wort, das euch verkündigt worden ist.',
    },
    2: {
        1: 'So legt nun ab alle Bosheit, allen Trug, alle Heuchelei und Mißgunst, Lästerung;',
        2: 'Als neugeborene Kindlein verlangt nach vernünftiger, lauterer Milch, auf daß ihr durch dieselbe zur Seligkeit gedeiht.',
        3: 'So ihr anders schon geschmeckt habt, wie gütig der Herr ist,',
        4: 'Zu Dem ihr hinzutretet, als zu einem lebendigen Steine, der von den Menschen verworfen, aber bei Gott auserwählt und in Ehren ist.',
        5: 'Und auch ihr seid wie lebendige Steine, aufgebaut zu einem geistigen Haus, einem heiligen Priestertum, um geistige Opfer darzubringen, die durch Jesus Christus Gott wohlgefällig sind.',
        6: 'Darum steht in der Schrift: Siehe, Ich lege auf Zion einen auserwählten, köstlichen Eckstein, und wer an ihn glaubt, wird nicht zuschanden werden.',
        7: 'Euch nun, die ihr glaubt, ist er köstlich, denen aber, die nicht glauben, ist er der Stein, den die Bauleute verworfen haben und der zum Eckstein geworden ist.',
        8: 'Ein Stein des Anstoßes und ein Fels zum Ärgernis für die, welche sich am Wort stoßen und nicht an dasselbe glauben, wozu sie auch bestimmt sind.',
        9: 'Ihr aber seid ein auserwählt Geschlecht, ein königlich Priestertum, ein heilig Volk, das Volk des Eigentums, daß ihr verkündigen sollt die Tugenden Dessen, Der euch aus der Finsternis in Sein wunderbares Licht berufen hat,',
        10: 'Die ihr vordem kein Volk ward, nun aber ein Volk Gottes, vordem nicht begnadigt, nun aber begnadigt seid.',
        11: 'Geliebte, ich ermahne euch als Fremdlinge und Pilger, euch fleischlicher Lüste zu enthalten, die wider die Seele streiten.',
        12: 'Führt einen guten Lebenswandel unter den Heiden, auf daß, wo sie euch Übles nachreden als Übeltätern, sie eure guten Werke sehen und Gott preisen am Tage der Heimsuchung.',
        13: 'So seid nun untertan aller menschlichen Ordnung um des Herrn willen, sowohl dem König, der die oberste Gewalt hat,',
        14: 'Als auch den Statthaltern, die von ihm ausgesandt sind zur Bestrafung der Übeltäter und zum Lobe der Rechtschaffenen.',
        15: 'Denn so ist es der Wille Gottes, daß ihr durch Gutestun die Unwissenheit der unverständigen Menschen zum Schweigen bringt.',
        16: 'Als Freie und nicht als ob ihr die Freiheit zum Deckmantel der Bosheit gebraucht, sondern als die Knechte Gottes.',
        17: 'Haltet jedermann in Ehren, liebet die Brüderschaft, fürchtet Gott, ehrt den König.',
        18: 'Ihr Knechte, seid untertan in aller Furcht den Herren, nicht allein den gütigen und gelinden, sondern auch den wunderlichen.',
        19: 'Denn das ist Gnade, wenn einer aus Gewissenhaftigkeit gegen Gott Widerwärtigkeiten erträgt und ungerecht leidet.',
        20: 'Denn was ist das für ein Ruhm, so ihr Unrecht tut und dafür Streiche zu erdulden habt; aber wenn ihr Recht tut und Leiden erduldet, das ist Gnade bei Gott.',
        21: 'Denn dazu seid ihr berufen; hat ja auch Christus für euch gelitten und euch ein Vorbild gelassen, daß ihr Seinen Fußstapfen nachfolgen sollt;',
        22: 'Er, Der keine Sünde getan, in Dessen Mund auch kein Trug erfunden worden ist;',
        23: 'Der nicht wieder schalt, da Er gescholten ward, nicht drohte, da Er litt; es Dem, Der da gerecht richtet, anheim stellte;',
        24: 'Der unsere Sünden Selbst an Seinem Leibe an das Holz hinauf nahm, auf daß wir, den Sünden abgestorben, der Gerechtigkeit leben, durch Dessen Wunden ihr geheilt worden seid.',
        25: 'Denn ihr ward wie die Schafe, die in der Irre gehen, seid nun aber zum Hirten und Bischof eurer Seelen zurückgekehrt.',
    },
    3: {
        1: 'Desgleichen sollen die Weiber ihren Männern untertan sein, auf daß auch die, so noch nicht an das Wort glauben, durch der Weiber Wandel ohne Wort gewonnen werden,',
        2: 'Wenn sie auf euren keuschen, gottesfürchtigen Wandel sehen.',
        3: 'Darum sei ihr Schmuck nicht der äußere, bestehend in Haarflechten, im Anlegen von Goldgeschmeide, oder in Gewändern,',
        4: 'Sondern der verborgene Mensch des Herzens, in unvergänglichem Wesen, mit sanftem und stillem Geiste, der köstlich ist vor den Augen Gottes.',
        5: 'Denn also haben sich vor Zeiten die heiligen Weiber geschmückt, die ihre Hoffnung auf Gott setzten und ihren Männern untertan waren,',
        6: 'Wie Sarah Abraham untertan war und ihn Herr nannte, deren Töchter ihr geworden seid, so ihr wohl tut und euch vor keinem Schrecknisse fürchtet.',
        7: 'Desgleichen ihr Männer, geht mit ihnen verständig um, als mit dem schwächeren Werkzeug, und beweist ihnen Ehre als Miterben der Gnade des Lebens, auf daß euer Gebet Erhörung finde.',
        8: 'Seid überhaupt allesamt gleichen Sinnes, teilnehmend, brüderlich, barmherzig und wohlwollend.',
        9: 'Vergeltet nicht Böses mit Bösem, nicht Scheltwort mit Scheltwort, segnet vielmehr und seid eingedenk, daß ihr dazu berufen seid, daß ihr Segen ererbet.',
        10: 'Denn wer des Lebens froh sein und gute Tage sehen will, der bewahre seine Zunge vor Bösem und seine Lippen, daß sie nichts Trügliches reden.',
        11: 'Er wende sich ab vom Bösen und tue Gutes, suche Frieden und jage ihm nach.',
        12: 'Denn die Augen des Herrn merken auf die Gerechten, und Seine Ohren auf ihr Gebet; das Angesicht des Herrn wendet sich wider die, so Böses tun.',
        13: 'Und wer ist, der euch Übles tun könnte, so ihr dem Guten nachkommt?',
        14: 'Und ob ihr auch leidet um der Gerechtigkeit willen, so seid ihr doch selig; fürchtet euch aber nicht vor dem, womit sie euch schrecken wollen, und seid unverzagt.',
        15: 'Christus den Herrn aber haltet heilig in euren Herzen; seid allezeit bereit, jedem Rede zu stehen, der von euch Grund fordert für die Hoffnung, die in euch ist,',
        16: 'Und das mit Sanftmut und Ehrfurcht vor Gott, indem ihr ein gutes Gewissen habt, daß sie, die von euch Übles reden als von Übeltätern, darob zuschanden werden, daß sie euren guten Wandel in Christus geschmäht haben,',
        17: 'Denn es ist besser, so es Gottes Wille ist, daß ihr leidet ob dem Gutestun, denn ob dem Übeltun.',
        18: 'Weil auch Christus einmal für unsere Sünden gelitten hat, der Gerechte für die Ungerechten, auf daß Er uns zu Gott brächte, und ist getötet worden dem Leibe nach, und lebendig gemacht nach dem Geiste,',
        19: 'In welchem Er auch hingegangen ist und den Geistern im Gefängnis gepredigt hat,',
        20: 'Die vordem ungläubig waren, da Gottes Langmut harrte in den Tagen Noachs, als man die Arche zurichtete, in die wenige, das heißt nur acht',
        21: 'Welches nun auch euch selig macht im Gegenbild der Taufe, nicht als die Abwaschung des Unrats am Fleische, sondern als der Bund eines guten Gewissens mit Gott durch die Auferstehung Jesu Christi;',
        22: 'Der zur Rechten Gottes ist, nachdem Er in den Himmel aufgefahren, wo die Engel, Gewalten und Kräfte Ihm untertänig sind.',
    },
    4: {
        1: 'Weil nun Christus für uns dem Fleische nach gelitten hat, so wappnet auch ihr euch mit dem gleichen Gedanken. Denn der am Fleische gelitten hat, ist abgebracht vom Sündigen.',
        2: 'Daß er hinfort, solange er noch im Fleische lebt, nicht menschlichen Lüsten, sondern dem Willen Gottes lebe.',
        3: 'Denn es ist genug, daß wir die vergangene Zeit des Lebens nach dem Willen der Heiden in Ausschweifungen, Wollüsten, Trunksucht, Schwelgereien, Zechgelagen, greulichen Abgöttereien hingebracht haben.',
        4: 'Das befremdet sie, daß ihr nicht mehr in demselben wüsten, unordentlichen Wesen mit ihnen fortlaufet, und da lästern sie euch;',
        5: 'Sie müssen aber Rechenschaft geben Dem, Der nun bereit ist zu richten die Lebendigen und die Toten.',
        6: 'Denn dazu ist auch den Toten das Evangelium gepredigt worden, auf daß sie als Menschen nach dem Fleische gerichtet würden, im Geiste aber Gott wohlgefällig leben könnten.',
        7: 'Es ist aber das Ende aller Dinge nahe gekommen.',
        8: 'So seid nun mäßig und nüchtern zum Gebet. Vor allem aber habt eine herzliche Liebe zueinander; denn die Liebe deckt auch der Sünden Menge.',
        9: 'Seid gastfrei untereinander, ohne Murren.',
        10: 'Und dient einander, ein jeglicher mit der Gabe, die er empfangen hat, als gute Haushalter der mannigfaltigen Gnade Gottes.',
        11: 'So einer redet, rede er nach Gottes Wort. So jemand ein Amt hat, so warte er des Amtes nach dem Vermögen, das Gott ihm gibt, auf daß in allen Dingen Gott durch Jesus Christus gepriesen werde, Welchem sei Ehre und Gewalt von Ewigkeit zu Ewigkeit! Amen.',
        12: 'Lasset euch nicht befremden, Geliebte, daß unter euch das Feuer der Prüfung für euch auskommt, als ob euch etwas Absonderliches widerführe.',
        13: 'Freut euch vielmehr darüber, auf daß ihr, inwieweit ihr an Christus Leiden teilhaben dürft, euch auch bei der Offenbarung Seiner Herrlichkeit freuen und frohlocken mögt.',
        14: 'Selig seid ihr, wenn ihr über Christus Namen geschmäht werdet, weil der Geist der Herrlichkeit und Gottes sich auf euch niederläßt; denn von ihnen wird Er verlästert, in euch aber verherrlicht.',
        15: 'Niemand unter euch leide als ein Mörder oder Dieb oder Übeltäter oder als einer, der sich in fremde Händel mischt.',
        16: 'Leidet er aber als Christ, so schäme er sich dessen nicht, sondern preise Gott dafür.',
        17: 'Denn es ist die Zeit, da das Gericht anfängt an dem Hause Gottes; wenn aber zuerst bei uns, was wird es für ein Ende nehmen bei denen, die dem Evangelium Gottes nicht glauben?',
        18: 'Und so der Gerechte kaum erhalten wird, wo wird der Gottlose und Sünder zu stehen kommen?',
        19: 'Darum sollen die, so da leiden nach dem Willen Gottes, Ihm, Dem treuen Schöpfer, ihre Seelen empfehlen und Gutes tun.',
    },
    5: {
        1: 'Die Ältesten, die unter euch sind, ermahne ich als Mitältester und Zeuge von Christus Leiden und Teilhaber der Herrlichkeit, die geoffenbart werden soll:',
        2: 'Weidet die Herde Gottes, die euch anvertraut ist, und haltet Aufsicht, nicht zwangsweise, sondern williglich, auch nicht schändlichen Gewinnes wegen, sondern aus Herzensgrund;',
        3: 'Nicht wie solche, die über die ihnen Zugewiesenen herrschen, sondern der Herde Vorbilder werden wollen;',
        4: 'So werdet ihr, wenn der Erzhirte kommt, einen unverwelklichen Ehrenkranz erhalten.',
        5: 'Desgleichen ihr Jüngere seid untertan den Ältesten. Ihr allesamt, willfahrt einander und haltet fest an der Demut, denn Gott widersteht den Hoffärtigen, aber den Demütigen gibt Er Gnade.',
        6: 'So demütigt euch nun unter die gewaltige Hand Gottes, daß Er euch erhöhe zu Seiner Zeit.',
        7: 'Alle eure Sorge werfet auf Ihn; denn Er sorgt für euch.',
        8: 'Seid nüchtern und wachet, denn euer Widersacher, der Teufel, geht umher wie ein brüllender Löwe, und sucht, wen er verschlinge.',
        9: 'Widersteht ihm fest im Glauben und seid eingedenk, daß dieselben Leiden auch über eure Brüder in der Welt ergehen.',
        10: 'Aber der Gott aller Gnade, Der euch berufen hat zu Seiner ewigen Herrlichkeit in Christo Jesu, wird euch, nachdem ihr eine kleine Zeit gelitten habt, vollbereiten, stärken, kräftigen, auf festen Grund stellen.',
        11: 'Ihm sei Ehre und Macht von Ewigkeit zu Ewigkeit! Amen.',
        12: 'Durch Silvanus, euren treuen Bruder, wie ich achte, habe ich dies wenige geschrieben, um euch zu ermahnen und zu bezeugen, daß dies die wahre Gnade Gottes ist, bei der ihr beharren sollt.',
        13: 'Es grüßt euch die miterwählte',
        14: 'Grüßet einander mit dem Kusse der Liebe. Friede sei mit euch allen, die in Christo Jesu sind! Amen.',
    },
}
